  var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;var proof=typeof(GameEngine).GetMethod("IsSuspendedGuoSiCompletedParent",flags)??throw new InvalidOperationException("Missing exact completed-parent proof.");
