 private static void Offer(GameEngine g)=>Reach(g,()=>P(g)?.SkillPrompt?.SkillId=="ol:sidao"&&P(g)!.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="activate"));
 private static void Activate(GameEngine g)=>Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="activate");
 private static void Native(GameEngine g,int target){var a=g.GetHumanLegalActions().First(a=>a.CardId is not null&&a.Kind!=LegalActionKind.UseProgramSkill&&(target==0?a.Kind==LegalActionKind.DrawTwo:a.TargetSeats.SequenceEqual([target])));Accept(g,new PlayCardCommand(0,a.CardId!.Value,a.TargetSeats,g.Revision,P(g)!.PromptId,a.PlayedCardKind,a.TargetCardId){ConversionSource=a.ConversionSource});}
 private static PendingDecision? P(GameEngine g)=>Enumerable.Range(0,4).Select(s=>g.CreateSnapshot(s).PendingDecision).FirstOrDefault(p=>p is not null);
 private static IEnumerable<T>E<T>(GameEngine g)where T:IGameEvent=>g.Events.Select(e=>e.Payload).OfType<T>();
 private static void Need(bool value,string message){if(!value)throw new InvalidOperationException(message);}
 private static void Accept(GameEngine g,GameCommand c){var result=g.Submit(CommandJson.Deserialize(CommandJson.Serialize([c])).Single());Need(result.Accepted,result.Error?.Message??"Rejected Guo Si native command.");}
 private static void Answer(GameEngine g,Func<PromptChoice,bool> predicate){var p=P(g)!;Accept(g,new AnswerPromptCommand(p.PlayerSeat,p.PromptId,p.Choices.First(predicate).Id,g.Revision));}
 private static void Play(GameEngine g)=>Reach(g,()=>P(g)is{Kind:DecisionKind.PlayCard,PlayerSeat:0});
 private static void Reach(GameEngine g,Func<bool> done){for(var n=0;n<180;n++){if(done())return;var p=P(g);if(p?.PlayerSeat==0&&p.Choices.Any(c=>c.Parameters.GetValueOrDefault("action")=="target-card-slot"))Answer(g,c=>c.Parameters.GetValueOrDefault("action")=="target-card-slot");else if(p is{PlayerSeat:0,Kind:DecisionKind.RespondDodge or DecisionKind.RespondSlash or DecisionKind.RescueDying}&&p.Choices.Any(c=>c.Parameters.GetValueOrDefault("response")is"take-damage"or"pass"or"let-die"))Answer(g,c=>c.Parameters.GetValueOrDefault("response")is"take-damage"or"pass"or"let-die");else if(p?.PlayerSeat==0&&p.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="skip"))Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="skip");else Accept(g,new AdvanceOneStepCommand(g.Revision));}throw new InvalidOperationException("Guo Si boundary missing "+JsonSerializer.Serialize(new{Prompt=P(g)?.Kind,Skill=P(g)?.SkillPrompt?.SkillId,Frames=g.ResolutionStack.Select(f=>new{f.Id,f.Kind}),Recent=g.Events.TakeLast(8).Select(e=>e.Payload.GetType().Name)}));}
 private static string State(GameEngine g)=>JsonSerializer.Serialize(new{Views=Enumerable.Range(0,4).Select(s=>SnapshotJson.Serialize(g.CreateSnapshot(s))),Frames=g.ResolutionStack.Select(f=>JsonSerializer.Serialize(f,f.GetType())),Events=g.Events.Select(e=>JsonSerializer.Serialize(e.Payload,e.Payload.GetType())),g.CardMovements});
 private static GameEngine Cold(GameEngine g,ContentRegistry r){var cold=GameReplay.Restore(GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(g.CreateCheckpoint())),r);Need(State(g)==State(cold),"Cold prefixes retain private choices, native receipt and once-paid returns.");return cold;}
 private static string Read(string suffix){using var stream=typeof(StandardClassicGeneralPackage).Assembly.GetManifestResourceStream("CardGame.Content.Standard.SkillPrograms.ol-guo-si."+suffix)!;using var reader=new StreamReader(stream);return reader.ReadToEnd();}
